def read_programme_identity(certificate, identity):
    """Exact original Identity3 body, fully debited before scalar strings."""
    if certificate.common_certificate is None:
        raise HeaderBoundsError("programme_identity_certificate_unavailable")
    _validate(certificate.connection, certificate)
    row = certificate.rows.get(("operator_identities", identity))
    if row is None:
        if identity in certificate.absent:
            return None
        raise HeaderBoundsError("header_row_unavailable")
    certificate.budget.debit(row[1], appearance=("programme-identity-body", identity))
    query = ('SELECT "id","created_at","revoked_at" FROM operator_identities WHERE id COLLATE BINARY=? LIMIT 2'
        if certificate.metadata_budget is not None and certificate.raw_owner is None else
        'SELECT "id","created_at","revoked_at" FROM operator_identities WHERE id=? LIMIT 2')
    records = list(_sql(certificate.connection, query, (identity,)))
    if len(records) != 1:
        raise HeaderBoundsError("header_row_unavailable")
    return tuple(records[0])



def _programme_pointer_metadata_matches(rows, expected, budget, row_count, planning_upper):
    """Compare paid metadata against fixed Source tuples without row copies."""
    # Fixed state32; row lengths/counter outputs8 each; scalar equality and
    # column counter6 per cell. Expectations are compiler constants, not
    # newly created runtime row/list/dict containers.
    budget.debit(planning_upper,
        appearance=("task-method-pointer", "stream-validation"))
    if len(rows) != row_count:
        return False
    row_index = 0
    while row_index < row_count:
        row = rows[row_index]
        fixed = expected[row_index]
        if len(row) != len(fixed):
            return False
        cell_index = 0
        while cell_index < len(fixed):
            if row[cell_index] != fixed[cell_index]:
                return False
            cell_index += 1
        row_index += 1
    return True


