def _selected_schema_census_sql():
    """Closed ORIGINAL schema policy; no caller SQL or schema-name input."""
    def quote(value):
        return "'" + value.replace("'", "''") + "'"
    def members(values):
        return ", ".join(quote(value) for value in sorted(values))
    tables = {*_SCHEMA_TABLES, "alembic_version"}
    auto_max = dict(_AUTO_MAX)
    auto_max.setdefault("alembic_version", 1)
    auto_cases = []
    for table, bound in sorted(auto_max.items()):
        prefix = "sqlite_autoindex_" + table + "_"
        suffix = f"substr(name, {len(prefix) + 1})"
        auto_cases.append(f"WHEN tbl_name = {quote(table)} THEN ("
            f"{suffix} <> '' AND instr(name, char(0)) = 0 AND "
            f"{suffix} NOT GLOB '*[^0-9]*' AND CAST({suffix} AS INTEGER) BETWEEN 1 AND {bound})")
    auto = "CASE " + " ".join(auto_cases) + " ELSE 0 END"
    prefix = "'sqlite_autoindex_' || tbl_name || '_'"
    task_names = {"ix_task_method_active_goal_id", "ix_task_method_active_owner_identity_id"}
    index = (f"CASE WHEN substr(name, 1, length({prefix})) = ({prefix}) COLLATE BINARY THEN ({auto}) "
        f"WHEN tbl_name = 'task_method_active' OR name IN ({members(task_names)}) "
        f"THEN (tbl_name = 'task_method_active' AND name IN ({members(task_names)})) "
        f"ELSE (tbl_name IN ({members(tables)}) AND name IN ({members(_NAMED_INDEXES)})) END")
    triggers = [f"(name = {quote(name)} AND tbl_name = {quote(spec[1])})"
        for name, spec in _FTS_SQL.items() if spec[0] == "trigger"]
    trigger = ("(tbl_name = 'operator_sessions' AND name IN "
        "('operator_principal_required_insert', 'operator_principal_required_update')) OR "
        + " OR ".join(triggers))
    valid = (f"CASE type WHEN 'table' THEN (name = tbl_name COLLATE BINARY AND "
        f"name IN ({members(tables | {'sqlite_sequence'} | set(_FTS_META))})) "
        f"WHEN 'index' THEN ({index}) WHEN 'trigger' THEN ({trigger}) ELSE 0 END")
    ordinal = "CASE name " + " ".join(f"WHEN {quote(name)} THEN {index}"
        for index, name in enumerate(_FTS_SQL, 1)) + " ELSE 0 END"
    return ("WITH capped AS (SELECT rowid, "
        "CASE WHEN octet_length(type) <= 7 THEN type END AS type, "
        "CASE WHEN octet_length(name) <= 128 THEN name END AS name, "
        "CASE WHEN octet_length(tbl_name) <= 128 THEN tbl_name END AS tbl_name "
        "FROM sqlite_schema ORDER BY rowid LIMIT 1360) "
        f"SELECT rowid, CASE WHEN ({valid}) THEN 1 ELSE 0 END AS original_object_valid, "
        f"{ordinal} AS original_fts_name_ordinal FROM capped ORDER BY rowid LIMIT 1360")


def _census_decimal_width(value):
    if type(value) is not int or not 0 <= value < 2**63:
        raise HeaderBoundsError("header_schema_object_unavailable")
    width = 1
    while value >= 10:
        value //= 10
        width += 1
    return width


def _census_source_leaves():
    # Source aliases only: no runtime roster tuple, item pairs or body copies.
    def keys(roster):
        for value in roster:
            if (type(value) is not str or not value or len(value) > 128
                    or any(not 32 <= ord(char) < 127 or char in "'\\\"" for char in value)):
                raise HeaderBoundsError("header_schema_source_unavailable")
    keys(_SCHEMA_TABLES)
    keys(_NAMED_INDEXES)
    # Exact streamed token membership requires delimiter-free source leaves.
    for name in _NAMED_INDEXES:
        if "|" in name:
            raise HeaderBoundsError("header_schema_source_unavailable")
    keys(_AUTO_MAX)
    keys(_FTS_SQL)
    keys(_FTS_META)
    for table in _AUTO_MAX:
        _census_decimal_width(_AUTO_MAX[table])
    for name in _FTS_SQL:
        spec = _FTS_SQL[name]
        if type(spec) is not tuple or len(spec) != 3 or type(spec[2]) is not str:
            raise HeaderBoundsError("header_schema_source_unavailable")
        kind = spec[0]
        table = spec[1]
        if (type(kind) is not str or kind not in ("table", "trigger")
                or type(table) is not str or not table or len(table) > 128
                or any(not 32 <= ord(char) < 127 or char in "'\\\"" for char in table)):
            raise HeaderBoundsError("header_schema_source_unavailable")
    if len(_FTS_SQL) != 15:
        raise HeaderBoundsError("header_schema_source_unavailable")


def _census_named_group_tables():
    # Source leaves only: no prefix roster, grouping dict or sorted lists.
    yield from _SCHEMA_TABLES
    if "task_method_active" not in _SCHEMA_TABLES:
        yield "task_method_active"


def _census_named_group_table(name):
    # The longest source table prefix partitions names independently of tbl_name.
    if not name.startswith(("ix_", "ux_")):
        return None
    selected = None
    width = 0
    for table in _census_named_group_tables():
        size = len(table)
        if (size > width and name.startswith(table, 3)
                and len(name) > size + 3 and name[size + 3] == "_"):
            selected = table
            width = size
    return selected


def _selected_schema_census_parts(*, numeric, factored_named=False, factored_auto=False):
    # Numeric mode emits widths only, and never sorts, formats or builds SQL.
    def part(value):
        return len(value) if numeric else value
    def number(value):
        return _census_decimal_width(value) if numeric else str(value)
    def quote(value):
        yield part("'")
        yield part(value)
        yield part("'")
    def members(values, *, source_order=False):
        first = True
        for value in values if numeric or source_order else sorted(values):
            if not first:
                yield part(", ")
            first = False
            yield from quote(value)
    def tables(extra=False):
        # Both passes traverse original leaves; neither builds a set/sorted list.
        yield from _SCHEMA_TABLES
        if "alembic_version" not in _SCHEMA_TABLES:
            yield "alembic_version"
        if extra:
            if "sqlite_sequence" not in _SCHEMA_TABLES:
                yield "sqlite_sequence"
            for name in _FTS_META:
                if name not in _SCHEMA_TABLES and name not in ("alembic_version", "sqlite_sequence"):
                    yield name
    def auto_keys():
        if numeric:
            yield from _AUTO_MAX
            if "alembic_version" not in _AUTO_MAX:
                yield "alembic_version"
        else:
            values = dict(_AUTO_MAX)
            values.setdefault("alembic_version", 1)
            yield from sorted(values)
    def suffix():
        yield part("substr(name, length('sqlite_autoindex_' || tbl_name || '_') + 1)")
    def auto():
        yield from suffix()
        yield part(" <> '' AND instr(name, char(0)) = 0 AND ")
        yield from suffix()
        yield part(" NOT GLOB '*[^0-9]*' AND CAST(")
        yield from suffix()
        if factored_auto:
            yield part(" AS INTEGER) BETWEEN 1 AND (")
            yield part(_AUTO_LOOKUP)
            yield part(")")
        else:
            yield part(" AS INTEGER) BETWEEN 1 AND (CASE tbl_name ")
            first = True
            for table in auto_keys():
                if not first:
                    yield part(" ")
                first = False
                yield part("WHEN ")
                yield from quote(table)
                yield part(" THEN ")
                yield number(_AUTO_MAX.get(table, 1))
            yield part(" ELSE 0 END)")
    def named_indexes():
        first_group = True
        if factored_named:
            yield part(_FACTORED_MEMBERSHIP)
            first_group = False
        else:
            for kind in ("ix_", "ux_"):
                for table in _census_named_group_tables():
                    first = True
                    for value in _NAMED_INDEXES:
                        if (not value.startswith(kind) or not value.startswith(table, 3)
                                or len(value) <= len(table) + 3 or value[len(table) + 3] != "_"
                                or _census_named_group_table(value) != table):
                            continue
                        offset = len(table) + 4
                        if first:
                            if not first_group:
                                yield part(" OR ")
                            first_group = False
                            yield part("(substr(name, 1, ")
                            yield number(offset)
                            yield part(") = '")
                            yield part(kind)
                            yield part(table)
                            yield part("_' COLLATE BINARY AND instr('")
                        first = False
                        yield part("|")
                        # Sizing never slices a source name; the paid pass does once.
                        yield len(value) - offset if numeric else value[offset:]
                    if not first:
                        yield part("|', '|' || substr(name, ")
                        yield number(offset + 1)
                        yield part(") || '|') > 0)")
        first = True
        for value in _NAMED_INDEXES:
            if _census_named_group_table(value) is not None:
                continue
            if first:
                if not first_group:
                    yield part(" OR ")
                yield part("(name IN (")
            else:
                yield part(", ")
            first = False
            yield from quote(value)
        if not first:
            yield part("))")
        if first_group and first:
            yield part("0")
    def index():
        yield part("CASE WHEN substr(name, 1, length('sqlite_autoindex_' || tbl_name || '_')) = ('sqlite_autoindex_' || tbl_name || '_') COLLATE BINARY THEN (")
        yield from auto()
        yield part(") WHEN tbl_name = 'task_method_active' OR name IN (")
        task = ("ix_task_method_active_goal_id", "ix_task_method_active_owner_identity_id")
        yield from members(task)
        yield part(") THEN (tbl_name = 'task_method_active' AND name IN (")
        yield from members(task)
        yield part(")) ELSE (tbl_name IN (")
        yield from members(tables(), source_order=True)
        # SUBSTR stops at embedded NUL; original full-name IN never accepts it.
        yield part(") AND instr(name, char(0)) = 0 AND instr(name, '|') = 0 AND (")
        yield from named_indexes()
        yield part(")) END")
    def trigger():
        yield part("(tbl_name = 'operator_sessions' AND name IN ('operator_principal_required_insert', 'operator_principal_required_update')) OR ")
        first = True
        for name in _FTS_SQL:
            spec = _FTS_SQL[name]
            if spec[0] != "trigger":
                continue
            if not first:
                yield part(" OR ")
            first = False
            yield part("(name = ")
            yield from quote(name)
            yield part(" AND tbl_name = ")
            yield from quote(spec[1])
            yield part(")")
    yield part("WITH capped AS (SELECT rowid, CASE WHEN octet_length(type) <= 7 THEN type END AS type, CASE WHEN octet_length(name) <= 128 THEN name END AS name, CASE WHEN octet_length(tbl_name) <= 128 THEN tbl_name END AS tbl_name FROM sqlite_schema ORDER BY rowid LIMIT 1360) SELECT rowid, CASE WHEN (CASE type WHEN 'table' THEN (name = tbl_name COLLATE BINARY AND name IN (")
    yield from members(tables(True), source_order=True)
    yield part(")) WHEN 'index' THEN (")
    yield from index()
    yield part(") WHEN 'trigger' THEN (")
    yield from trigger()
    yield part(") ELSE 0 END) THEN 1 ELSE 0 END AS original_object_valid, CASE name ")
    ordinal = 0
    for name in _FTS_SQL:
        ordinal += 1
        if ordinal != 1:
            yield part(" ")
        yield part("WHEN ")
        yield from quote(name)
        yield part(" THEN ")
        yield number(ordinal)
    yield part(" ELSE 0 END AS original_fts_name_ordinal FROM capped ORDER BY rowid LIMIT 1360")


def _selected_schema_census_input_upper(*, aggregate=False):
    _census_source_leaves()
    length = count = 0
    parts = (_selected_schema_factored_auto_aggregate_parts(numeric=True) if aggregate
        else _selected_schema_census_parts(numeric=True))
    for width in parts:
        length += width
        count += 1
    # One join frontier, final SQL and original driver's input copy.
    upper = 2 + length + 2 * count + max(0, count - 1) + 2 * (length + 2) + 6
    # Container slots/aliases are charged too, including original FTS DDL refs.
    # Two table branches now stream: remove ONLY their two set and two sorted
    # list appearances (4*2230). Retain the other four source/union alias reserves.
    upper += 4 * (2 + sum(len(value) + 3 for value in _SCHEMA_TABLES))
    # Groups stream original leaves: no named sort/list/dict/prefix allocation.
    # Every matched name is sliced once in the paid fragment stream.
    for name in _NAMED_INDEXES:
        table = _census_named_group_table(name)
        if table is not None:
            upper += len(name) - len(table) - 4 + 2
    # Two formatted decimal offsets per occupied group, each one actual string.
    for kind in ("ix_", "ux_"):
        for table in _census_named_group_tables():
            for name in _NAMED_INDEXES:
                if (name.startswith(kind) and name.startswith(table, 3)
                        and len(name) > len(table) + 3 and name[len(table) + 3] == "_"
                        and _census_named_group_table(name) == table):
                    upper += _census_decimal_width(len(table) + 4) + 2
                    upper += _census_decimal_width(len(table) + 5) + 2
                    break
    # Other source rosters retain their existing conservative slot appearances.
    upper += 6 * (2 + sum(len(value) + 3 for value in _AUTO_MAX))
    upper += 6 * (2 + sum(len(value) + 3 for value in _FTS_META))
    upper += 3 * (2 + sum(3 + len(name) + 2 + _metadata_size(_FTS_SQL[name]) + 1 for name in _FTS_SQL))
    upper += 3 * (2 + sum(len(table) + 3 + 20 for table in _AUTO_MAX))
    # Each CASE bound is formatted once; dynamic auto suffix has no offset string.
    for table in _AUTO_MAX:
        upper += _census_decimal_width(_AUTO_MAX[table]) + 2
    if "alembic_version" not in _AUTO_MAX:
        upper += 3
    for ordinal in range(1, len(_FTS_SQL) + 1):
        upper += _census_decimal_width(ordinal) + 2
    # Literal task/default/union slots, not retained new source authority.
    upper += 6 * (2 + len("alembic_version") + 3 + len("sqlite_sequence") + 3)
    upper += 3 * (2 + len("ix_task_method_active_goal_id") + 3
        + len("ix_task_method_active_owner_identity_id") + 3)
    return upper


def _selected_schema_census_flat_sql():
    return "".join(_selected_schema_census_parts(numeric=False))


_CENSUS_AGGREGATE_PREFIX = 'SELECT * FROM (WITH projected AS ('
_CENSUS_AGGREGATE_SUFFIX = ") SELECT COUNT(*), (COALESCE(MAX(CASE WHEN typeof(rowid) != 'integer' OR rowid < -9223372036854775808 OR rowid > 9223372036854775807 OR typeof(original_object_valid) != 'integer' OR original_object_valid NOT IN (0,1) OR typeof(original_fts_name_ordinal) != 'integer' OR original_fts_name_ordinal NOT BETWEEN 0 AND 15 THEN 1 ELSE 0 END),0) | (COALESCE(MAX(CASE WHEN original_object_valid != 1 THEN 1 ELSE 0 END),0) << 1)), ((COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 1 THEN 1 ELSE 0 END),0) << 0) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 2 THEN 1 ELSE 0 END),0) << 1) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 3 THEN 1 ELSE 0 END),0) << 2) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 4 THEN 1 ELSE 0 END),0) << 3) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 5 THEN 1 ELSE 0 END),0) << 4) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 6 THEN 1 ELSE 0 END),0) << 5) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 7 THEN 1 ELSE 0 END),0) << 6) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 8 THEN 1 ELSE 0 END),0) << 7) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 9 THEN 1 ELSE 0 END),0) << 8) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 10 THEN 1 ELSE 0 END),0) << 9) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 11 THEN 1 ELSE 0 END),0) << 10) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 12 THEN 1 ELSE 0 END),0) << 11) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 13 THEN 1 ELSE 0 END),0) << 12) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 14 THEN 1 ELSE 0 END),0) << 13) | (COALESCE(MAX(CASE WHEN original_fts_name_ordinal = 15 THEN 1 ELSE 0 END),0) << 14)) FROM projected)"


def _selected_schema_census_aggregate_parts(*, numeric):
    yield len(_CENSUS_AGGREGATE_PREFIX) if numeric else _CENSUS_AGGREGATE_PREFIX
    yield from _selected_schema_census_parts(numeric=numeric)
    yield len(_CENSUS_AGGREGATE_SUFFIX) if numeric else _CENSUS_AGGREGATE_SUFFIX


_FACTORED_PREFIX = 'SELECT * FROM (WITH named_groups(prefix,tokens) AS (VALUES '
_FACTORED_MEMBERSHIP = "EXISTS(SELECT 1 FROM named_groups WHERE substr(name,1,length(prefix))=prefix COLLATE BINARY AND instr(tokens,'|'||substr(name,length(prefix)+1)||'|')>0)"


def _factored_named_group_parts(*, numeric):
    # Original source leaves; never a roster/group dictionary or list.
    def part(value):
        return len(value) if numeric else value
    first_group = True
    for kind in ("ix_", "ux_"):
        for table in _census_named_group_tables():
            first = True
            for value in _NAMED_INDEXES:
                if (not value.startswith(kind) or not value.startswith(table, 3)
                        or len(value) <= len(table) + 3 or value[len(table) + 3] != "_"
                        or _census_named_group_table(value) != table):
                    continue
                offset = len(table) + 4
                if first:
                    if not first_group:
                        yield part(",")
                    first_group = False
                    yield part("('")
                    yield part(kind)
                    yield part(table)
                    yield part("_','")
                first = False
                yield part("|")
                yield len(value) - offset if numeric else value[offset:]
            if not first:
                yield part("|')")
    # Mandatory nonempty numeric validation in owner-checked sizing pass.
    if first_group:
        raise HeaderBoundsError("header_schema_source_unavailable")


_AUTO_VALUES_PREFIX = '), auto_policy(table_name,max_value) AS (VALUES '
_AUTO_VALUES_POST = '), projected AS ('
_AUTO_LOOKUP = 'COALESCE((SELECT max_value FROM auto_policy WHERE table_name=tbl_name COLLATE BINARY),0)'


def _factored_auto_policy_parts(*, numeric):
    def part(value):
        return len(value) if numeric else value
    first = True
    # Original source leaves only; no dict(_AUTO_MAX), sorted/items pair list.
    for table in _AUTO_MAX:
        if not first:
            yield part(',')
        first = False
        yield part("('")
        yield part(table)
        yield part("',")
        yield _census_decimal_width(_AUTO_MAX[table]) if numeric else str(_AUTO_MAX[table])
        yield part(')')
    if 'alembic_version' not in _AUTO_MAX:
        if not first:
            yield part(',')
        # Stream same five fragments as ordinary rows for exact ledger parity.
        yield part("('")
        yield part('alembic_version')
        yield part("',")
        yield 1 if numeric else '1'
        yield part(')')


def _selected_schema_factored_auto_aggregate_parts(*, numeric):
    # Includes every CTE wrapper in the one full numeric/construction stream.
    yield len(_FACTORED_PREFIX) if numeric else _FACTORED_PREFIX
    yield from _factored_named_group_parts(numeric=numeric)
    yield len(_AUTO_VALUES_PREFIX) if numeric else _AUTO_VALUES_PREFIX
    yield from _factored_auto_policy_parts(numeric=numeric)
    yield len(_AUTO_VALUES_POST) if numeric else _AUTO_VALUES_POST
    yield from _selected_schema_census_parts(numeric=numeric,
        factored_named=True, factored_auto=True)
    yield len(_CENSUS_AGGREGATE_SUFFIX) if numeric else _CENSUS_AGGREGATE_SUFFIX


def _selected_schema_census_aggregate_input_upper():
    for value in (_FACTORED_PREFIX, _FACTORED_MEMBERSHIP, _AUTO_VALUES_PREFIX,
            _AUTO_VALUES_POST, _AUTO_LOOKUP, _CENSUS_AGGREGATE_SUFFIX):
        if type(value) is not str or not value.isascii():
            raise HeaderBoundsError("header_schema_source_unavailable")
    return _selected_schema_census_input_upper(aggregate=True)


def _selected_schema_census_aggregate_sql():
    return "".join(_selected_schema_factored_auto_aggregate_parts(numeric=False))


def _selected_census_summary(connection, budget):
    _selected_census_owner(connection, budget)
    upper = _selected_schema_census_aggregate_input_upper()
    _metadata_precharge(connection, budget, upper, ("complete-schema-flat-construction",))
    for stage in ("delivery", "row-copy", "encoded-copy"):
        _metadata_precharge(connection, budget, _metadata_upper(1, (4, 1, 5)),
            ("complete-schema", stage))
    for phase in ("source-name-delivery", "name-list-copy", "name-set-copy"):
        _metadata_precharge(connection, budget, 2 + sum(len(name) + 3 for name in _FTS_SQL) - 1,
            ("complete-schema-fts-decoding", phase))
    for phase in ("ordinal-visits", "ordinal-set-copy", "ordinal-sorted-copy"):
        _metadata_precharge(connection, budget, _metadata_upper(15, (2,)),
            ("complete-schema-fts-decoding", phase))
    query = _selected_schema_census_aggregate_sql()
    rows = list(_sql(connection, query, ()))
    if (len(rows) != 1 or len(rows[0]) != 3
            or any(type(value) is not int for value in rows[0])):
        raise HeaderBoundsError("header_schema_object_unavailable")
    count, flags, mask = rows[0]
    if not 0 <= count <= 1360 or not 0 <= flags <= 3 or not 0 <= mask <= 32767:
        raise HeaderBoundsError("header_schema_object_unavailable")
    if flags & 1:
        raise HeaderBoundsError("header_schema_object_unavailable")
    if count > _SCHEMA_LIMIT:
        raise HeaderBoundsError("header_schema_object_bound")
    if flags & 2:
        raise HeaderBoundsError("header_schema_object_unavailable")
    return mask


def _projected_schema_objects(connection, budget, *, _header_budget):
    if type(budget) is not HeaderReadBudget or _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    mask = _selected_census_summary(connection, budget)
    present = set()
    ordinal = 0
    for name in _FTS_SQL:
        if mask & (1 << ordinal):
            present.add(name)
        ordinal += 1
    return present


def _selected_census_owner(connection, budget):
    # Zero-debit owner check, before ANY source sizing/generator traversal.
    from src.memory.header_bounds import _SESSION_NUMERIC_READS, _MEMORY_LEDGER_PHASE
    if (type(budget) is not HeaderReadBudget or _SESSION_NUMERIC_READS.get() is not None
            or _MEMORY_LEDGER_PHASE.get() is not None):
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    _metadata_transaction_required(connection)
    current = _CURRENT.get()
    if current is not None and (current.connection is not connection or current.budget is not budget):
        raise HeaderBoundsError("header_metadata_owner_unavailable")


def _selected_census_rows(connection, budget):
    _selected_census_owner(connection, budget)
    upper = _selected_schema_census_input_upper()
    _metadata_precharge(connection, budget, upper, ("complete-schema-flat-construction",))
    # Pay ALL result copies before the join or query; no partial construction on exhaustion.
    for stage in ("delivery", "row-copy", "encoded-copy"):
        _metadata_precharge(connection, budget, _metadata_upper(1360, (20, 1, 2)),
            ("complete-schema", stage))
    query = _selected_schema_census_flat_sql()
    rows = list(_sql(connection, query, ()))
    if len(rows) > 1360:
        raise HeaderBoundsError("header_schema_object_bound")
    for row in rows:
        if (len(row) != 3 or any(type(value) is not int for value in row)
                or not -(2**63) <= row[0] < 2**63 or row[1] not in (0, 1)
                or not 0 <= row[2] <= 15):
            raise HeaderBoundsError("header_schema_object_unavailable")
    return rows


def _projected_schema_row_objects(connection, budget, *, _header_budget):
    if type(budget) is not HeaderReadBudget or _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    rows = _selected_census_rows(connection, budget)
    if len(rows) > _SCHEMA_LIMIT:
        raise HeaderBoundsError("header_schema_object_bound")
    if any(row[1] != 1 for row in rows):
        raise HeaderBoundsError("header_schema_object_unavailable")
    for phase in ("source-name-delivery", "name-list-copy", "name-set-copy"):
        _metadata_precharge(connection, budget, 2 + sum(len(name) + 3 for name in _FTS_SQL) - 1,
            ("complete-schema-fts-decoding", phase))
    for phase in ("ordinal-visits", "ordinal-set-copy", "ordinal-sorted-copy"):
        _metadata_precharge(connection, budget, _metadata_upper(1360, (2,)),
            ("complete-schema-fts-decoding", phase))
    ordinals = sorted({ordinal for _rowid, _valid, ordinal in rows if ordinal})
    names = tuple(_FTS_SQL)
    return {names[ordinal - 1] for ordinal in ordinals}


def _validate_fts_metadata(connection,budget,objects, *, _header_budget=None, _present_fts=None):
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    present=({name for _rowid,_kind,name,_table in objects if name in _FTS_SQL}
        if _present_fts is None else _present_fts)
    if not present:return  # An isolated pre-initialization/model-only schema.
    if present!=set(_FTS_SQL):raise HeaderBoundsError("header_fts_metadata_changed")
    for name,(kind,table,expected_sql) in _FTS_SQL.items():
        header=_metadata_rows(connection, "SELECT typeof(sql),octet_length(sql) FROM sqlite_schema WHERE name=? LIMIT 2", (name,), _header_budget=_header_budget, upper=_metadata_upper(2, (44,20)), appearance=('fts-sql-header',))
        if len(header)!=1 or tuple(header[0])!=("text",len(expected_sql.encode("utf-8"))):
            raise HeaderBoundsError("header_fts_metadata_changed")
        budget.debit(6*header[0][1]+2, appearance=("fts-sql", name))
        actual=_metadata_scalar(connection,"SELECT sql FROM sqlite_schema WHERE name=? LIMIT 2",(name,), _header_budget=_header_budget, width=6*len(expected_sql.encode("utf-8"))+2, appearance=("fts-sql-body",name), bounded_query="SELECT CASE WHEN octet_length(sql)<="+str(len(expected_sql.encode("utf-8")))+" THEN sql END FROM sqlite_schema WHERE name=? LIMIT 2")
        if actual!=expected_sql:raise HeaderBoundsError("header_fts_metadata_changed")
    for name,expected in _FTS_META.items():
        columns=_metadata_rows(connection, 'SELECT cid,CASE WHEN octet_length(name)<=128 THEN name END,'
            'CASE WHEN octet_length(type)<=128 THEN type END,"notnull",'
            'CASE WHEN dflt_value IS NULL THEN NULL WHEN octet_length(dflt_value)<=128 THEN dflt_value END,'
            'pk,hidden FROM pragma_table_xinfo(?) LIMIT ?', (name,len(expected["columns"])+1), _header_budget=_header_budget, upper=_metadata_upper((len(expected["columns"])+1), (20,770,770,20,770,20,20)), appearance=('fts-columns',))
        layout=_metadata_rows(connection, 'SELECT type,ncol,wr,strict FROM pragma_table_list WHERE schema="main" AND name=? LIMIT 2', (name,), _header_budget=_header_budget, upper=_metadata_upper(2, (44,20,20,20)), appearance=('fts-layout',))
        indexes=_metadata_rows(connection, 'SELECT seq,CASE WHEN octet_length(name)<=128 THEN name END,"unique",'
            'CASE WHEN octet_length(origin)<=2 THEN origin END,partial FROM pragma_index_list(?) LIMIT ?', (name,len(expected["indexes"])+1), _header_budget=_header_budget, upper=_metadata_upper((len(expected["indexes"])+1), (20,770,20,14,20)), appearance=('fts-indexes',))
        if _header_budget is None:
            budget.debit(_metadata_cost([list(x) for x in (*columns,*layout,*indexes)]), appearance=("fts-schema", name))
        if ([list(x) for x in columns]!=expected["columns"] or [list(x) for x in layout]!=[expected["table"]]
                or [list(x) for x in indexes]!=expected["indexes"]):
            raise HeaderBoundsError("header_fts_metadata_changed")
        for index,parts in expected["index_columns"].items():
            actual=_metadata_rows(connection, 'SELECT seqno,cid,CASE WHEN octet_length(name)<=128 THEN name END,'
                'desc,CASE WHEN octet_length(coll)<=128 THEN coll END,key FROM pragma_index_xinfo(?) LIMIT ?', (index,len(parts)+1), _header_budget=_header_budget, upper=_metadata_upper((len(parts)+1), (20,20,770,20,770,20)), appearance=('fts-index-parts',))
            if _header_budget is None:
                budget.debit(_metadata_cost([list(x) for x in actual]), appearance=("fts-index", index))
            if [list(x) for x in actual]!=parts:raise HeaderBoundsError("header_fts_metadata_changed")


def preflight_composition_superset(connection,budget, *, raw_owner=None, _header_budget=None):
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    if type(budget) is not HeaderReadBudget:raise HeaderBoundsError("header_request_bound")
    if raw_owner is not None and _header_budget is not None:
        raise HeaderBoundsError("header_metadata_raw_owner_unavailable")
    state=_state(connection,raw_owner=raw_owner,_header_budget=_header_budget)
    if raw_owner is not None:
        raw_owner._validate_budget(budget)
    cookies=_snapshot_schema_cookies(connection,budget,_header_budget=_header_budget) if raw_owner is not None else None
    if tuple(map(int,_metadata_scalar(connection,"SELECT sqlite_version()", _header_budget=_header_budget, width=770, appearance=("sqlite-version",), bounded_query="SELECT CASE WHEN octet_length(sqlite_version())<=128 THEN sqlite_version() END").split('.'))) < (3,43,0) or _metadata_scalar(connection,"PRAGMA encoding", _header_budget=_header_budget, width=32, appearance=("sqlite-encoding",))!="UTF-8":
        raise HeaderBoundsError("header_sqlite_version_unsupported")
    if _header_budget is None:
        objects=_metadata_rows(connection, 'SELECT rowid,CASE WHEN octet_length(type)<=7 THEN type END,'
            'CASE WHEN octet_length(name)<=128 THEN name END,CASE WHEN octet_length(tbl_name)<=128 THEN tbl_name END '
            'FROM sqlite_schema ORDER BY rowid LIMIT 1360', (), _header_budget=_header_budget, upper=_metadata_upper(1360, (20,44,770,770)), appearance=('complete-schema',))
        if len(objects)>_SCHEMA_LIMIT:raise HeaderBoundsError("header_schema_object_bound")
        for _id,kind,name,table in objects:
            if kind=="table":valid=name==table and name in {*_SCHEMA_TABLES,"sqlite_sequence","alembic_version",*_FTS_META}
            elif kind=="index":
                valid=table in {*_SCHEMA_TABLES,"alembic_version"} and name in _NAMED_INDEXES
                task_method_indexes={"ix_task_method_active_goal_id","ix_task_method_active_owner_identity_id"}
                if table=="task_method_active" or name in task_method_indexes:
                    valid=table=="task_method_active" and name in task_method_indexes
                prefix="sqlite_autoindex_"+str(table)+"_"
                if isinstance(name,str) and name.startswith(prefix):
                    suffix=name[len(prefix):]
                    valid=suffix.isascii() and suffix.isdecimal() and 1<=int(suffix)<=_AUTO_MAX.get(table,1 if table=="alembic_version" else 0)
            elif kind=="trigger":valid=(table=="operator_sessions" and name in {"operator_principal_required_insert","operator_principal_required_update"}) or (name in _FTS_SQL and _FTS_SQL[name][:2]==("trigger",table))
            else:valid=False
            if not valid:raise HeaderBoundsError("header_schema_object_unavailable")
        if _header_budget is None:
            budget.debit(_metadata_cost([list(r) for r in objects]), appearance=("complete-schema",))
        _validate_fts_metadata(connection,budget,objects,_header_budget=_header_budget)
    else:
        present = _projected_schema_objects(connection, budget, _header_budget=_header_budget)
        _validate_fts_metadata(connection, budget, None, _header_budget=_header_budget, _present_fts=present)
    allrows={}
    for descriptor in COMPOSITION_DESCRIPTORS.values():
        ids=_discover(connection,descriptor,budget,remaining=MAX_ROWS-len(allrows),
            database_identity=raw_owner._namespace if raw_owner is not None else None,_header_budget=_header_budget)
        rows=_headers(connection,descriptor,ids,_header_budget=_header_budget)
        budget.debit(sum(cost for _,cost in rows.values()), appearance=("complete-headers", descriptor.table, tuple(ids)))
        allrows.update(rows)
    if _state(connection,raw_owner=raw_owner,_header_budget=_header_budget)!=state:raise HeaderBoundsError("header_snapshot_changed")
    if raw_owner is not None and _snapshot_schema_cookies(connection,budget,_header_budget=_header_budget)!=cookies:
        raise HeaderBoundsError("header_schema_cookie_changed")
    cert=CompositionHeaderCertificate(connection,*state,MappingProxyType(allrows),budget,_SEAL,
        raw_owner=raw_owner,schema_cookies=cookies,metadata_budget=_header_budget)
    object.__setattr__(cert,"issued_id",id(cert))
    return cert


async def certify_composition_superset(db,budget, *, _header_budget=None):
    if _header_budget is not None and _header_budget is not budget:
        raise HeaderBoundsError("header_metadata_owner_unavailable")
    scope = _checked_current_snapshot_scope(budget)
    if scope is not None and scope.session is not None and scope.session is not db:
        raise HeaderBoundsError("memory_snapshot_scope_unavailable")
    def certify_fresh(connection):
        # Public certification always pays and issues a fresh certificate.  Only
        # the resulting live writer snapshot may replace a stale reader entry.
        scope = _checked_current_snapshot_scope(budget)
        _check_snapshot_scope_connection(scope, connection)
        if scope is None:
            return preflight_composition_superset(connection, budget, _header_budget=_header_budget)
        cookies = _snapshot_schema_cookies(connection, budget, _header_budget=_header_budget)
        certificate = preflight_composition_superset(connection, budget, _header_budget=_header_budget)
        if _snapshot_schema_cookies(connection, budget, _header_budget=_header_budget) != cookies:
            raise HeaderBoundsError("header_schema_cookie_changed")
        _validate(connection, certificate)
        _SNAPSHOT_CERTIFICATES[id(certificate)] = certificate
        scope.certificates[connection] = (certificate, cookies)
        return certificate
    return await (await db.connection()).run_sync(certify_fresh)


async def validate_composition_certificate(db,certificate):
    await (await db.connection()).run_sync(lambda c:_validate(c,certificate))


@contextmanager
def snapshot_reads(certificate):
    _validate(certificate.connection,certificate)
    token=_CURRENT.set(certificate)
    raw_token = _RAW_METADATA_SNAPSHOT.set((certificate, _snapshot_current_task(), threading.get_ident()))
    try:yield
    finally:
        _RAW_METADATA_SNAPSHOT.reset(raw_token)
        _CURRENT.reset(token)


@asynccontextmanager
async def snapshot_reads_async(db, certificate):
    """Validate on the real driver greenlet before an original async execute."""
    await validate_composition_certificate(db, certificate)
    token = _CURRENT.set(certificate)
    try:
        yield
    finally:
        _CURRENT.reset(token)


def charge_row(connection,table,key):
    certificate=_CURRENT.get()
    if certificate is None:return
    _validate(connection,certificate)
    if table=="work_board_events" and type(key) is str:
        key=int(key)
    row=certificate.rows.get((table,key))
    if row is None:raise HeaderBoundsError("header_row_unavailable")
    certificate.budget.debit(row[1], appearance=("body", table, key))


def charge_table(connection,table):
    """Debit the certified finite table before original full inventory reads."""
    certificate=_CURRENT.get()
    if certificate is None:return
    _validate(connection,certificate)
    if table not in COMPOSITION_DESCRIPTORS:raise HeaderBoundsError("header_descriptor_unavailable")
    identities = tuple(key for name, key in certificate.rows if name == table)
    certificate.budget.debit(sum(cost for (name,_key),(_rowid,cost) in certificate.rows.items() if name==table),
        appearance=("table-body", table, identities))


def current_budget():
    cert=_CURRENT.get()
    return cert.budget if cert is not None else None
